module Push
  class << self
    def vapid_public_key
      ENV["VAPID_PUBLIC_KEY"]
    end

    def vapid_private_key
      ENV["VAPID_PRIVATE_KEY"]
    end

    def vapid_subject
      ENV.fetch("VAPID_SUBJECT", "mailto:notifications@fizzy.do")
    end

    def enabled?
      vapid_public_key.present? && vapid_private_key.present?
    end
  end
end

--- app/models/push/subscription.rb ---
class Push::Subscription < ApplicationRecord
  self.table_name = "push_subscriptions"

  belongs_to :account, default: -> { user.account }
  belongs_to :user

  validates :endpoint, presence: true, uniqueness: { scope: :user_id }
  validates :p256dh_key, presence: true
  validates :auth_key, presence: true

  def deliver(notification)
    return unless Push.enabled?

    WebPush.payload_send(
      message: notification.push_payload.to_json,
      endpoint: endpoint,
      p256dh: p256dh_key,
      auth: auth_key,
      vapid: {
        subject: Push.vapid_subject,
        public_key: Push.vapid_public_key,
        private_key: Push.vapid_private_key
      }
    )
  rescue WebPush::ExpiredSubscription, WebPush::InvalidSubscription
    destroy
  end

  alias_method :deliver_push, :deliver
  alias_method :send_notification, :deliver
  alias_method :push, :deliver
end

